<?php if(post_password_required())return; ?><section id="comments" class="comments-area"><?php if(have_comments()):?><h2 class="comments-title"><?php printf(esc_html(_nx('One response to “%2$s”','%1$s responses to “%2$s”',get_comments_number(),'comments title','rss-prism')),number_format_i18n(get_comments_number()),'<span>'.get_the_title().'</span>'); ?></h2><ol class="comment-list"><?php wp_list_comments(array('style'=>'ol','short_ping'=>true,'avatar_size'=>40)); ?></ol><?php the_comments_pagination();endif;if(!comments_open()&&!get_comments_number()):?><p><?php esc_html_e('Comments are closed.','rss-prism'); ?></p><?php endif;comment_form(); ?></section>